import React from 'react';

const DisabledComponent = ({ name }) => {
  return (
    <div style={{ 
      padding: '2rem', 
      textAlign: 'center', 
      backgroundColor: '#f8f9fa', 
      border: '2px dashed #dee2e6',
      borderRadius: '8px',
      margin: '1rem'
    }}>
      <h3 style={{ color: '#6c757d', marginBottom: '1rem' }}>
        {name} - Temporarily Disabled
      </h3>
      <p style={{ color: '#6c757d' }}>
        This component has been temporarily disabled to test Mapbox routing in isolation.
        <br />
        It will be re-enabled after routing issues are resolved.
      </p>
    </div>
  );
};

export default DisabledComponent;










