  // Check graph connectivity to ensure pathfinding will work
  const checkGraphConnectivity = (nodes, edges) => {
    const nodeIds = Object.keys(nodes);
    const connectedNodes = new Set();
    const disconnectedNodes = [];
    
    // Start from the first node and traverse the graph
    if (nodeIds.length > 0) {
      const queue = [nodeIds[0]];
      connectedNodes.add(nodeIds[0]);
      
      while (queue.length > 0) {
        const currentNode = queue.shift();
        const neighbors = edges[currentNode] || [];
        
        for (const neighbor of neighbors) {
          if (!connectedNodes.has(neighbor.nodeId)) {
            connectedNodes.add(neighbor.nodeId);
            queue.push(neighbor.nodeId);
          }
        }
      }
    }
    
    // Find disconnected nodes
    for (const nodeId of nodeIds) {
      if (!connectedNodes.has(nodeId)) {
        disconnectedNodes.push(nodeId);
      }
    }
    
    return {
      totalNodes: nodeIds.length,
      connectedNodes: connectedNodes.size,
      disconnectedNodes: disconnectedNodes.length,
      disconnectedNodeIds: disconnectedNodes,
      isFullyConnected: disconnectedNodes.length === 0
    };
  };

